<?php
require __DIR__.'/auth.php'; require_login(); require __DIR__.'/db.php';
$result=mysqli_query($conn,'SELECT event_id,event_name,description,event_date,poster FROM events ORDER BY event_date ASC');
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Events | StudentHub</title><script src="https://cdn.tailwindcss.com"></script><link rel="stylesheet" href="css/style.css"></head><body><main class="max-w-[1200px] mx-auto px-6 py-10"><header class="student-topbar"><div><p class="eyebrow">EVENTS</p><h1>Campus events</h1><p>Register for an upcoming event.</p></div><a class="student-logout" href="logout.php">Logout</a></header><section class="admin-event-list" id="events-list"><?php while($event=$result?$result->fetch_assoc():null): ?><article><h2><?=htmlspecialchars($event['event_name'],ENT_QUOTES,'UTF-8')?></h2><p><?=htmlspecialchars($event['event_date'].' — '.($event['description']?:'No description'),ENT_QUOTES,'UTF-8')?></p><?php if($event['poster']): ?><img class="admin-event-poster" src="uploads/posters/<?=rawurlencode($event['poster'])?>" alt="Poster for <?=htmlspecialchars($event['event_name'],ENT_QUOTES,'UTF-8')?>"><?php endif; ?><button type="button" data-event-id="<?=$event['event_id']?>">Register</button></article><?php endwhile; ?></section><p id="event-message" role="status" aria-live="polite"></p></main><script>document.querySelectorAll('[data-event-id]').forEach(button=>button.onclick=async()=>{const response=await fetch('api/register_event.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({event_id:button.dataset.eventId})});const data=await response.json();document.getElementById('event-message').textContent=data.message;if(data.success)button.disabled=true;});</script></body></html>
